   461	fn text(value: &Value, key: &str) -> Option<String> {
   462	    value.get(key)?.as_str().map(str::to_string)
   463	}
   464	
   465	fn finite_number(value: &Value, key: &str) -> Result<f64, String> {
   466	    value
   467	        .get(key)
   468	        .and_then(Value::as_f64)
   469	        .filter(|number| number.is_finite())
   470	        .ok_or_else(|| format!("{key} must be a finite number"))
   471	}
