   473	#[derive(Debug, PartialEq)]
   474	struct SampledPlot {
   475	    paths: Vec<String>,
   476	    y_min: f64,
   477	    y_max: f64,
   478	}
   479	
   480	fn sample_plot(
   481	    config: &PlotConfig,
   482	    parameters: &BTreeMap<String, f64>,
   483	) -> Result<SampledPlot, String> {
   484	    let mut values = parameters.clone();
   485	    let mut sampled = vec![Vec::with_capacity(config.x.samples); config.series.len()];
   486	    let mut y_min = f64::INFINITY;
   487	    let mut y_max = f64::NEG_INFINITY;
   488	
   489	    for sample in 0..config.x.samples {
   490	        let progress = sample as f64 / (config.x.samples - 1) as f64;
   491	        let x = config.x.min + progress * (config.x.max - config.x.min);
   492	        values.insert(config.x.id.clone(), x);
   493	        for (index, series) in config.series.iter().enumerate() {
   494	            let y = series
   495	                .expression
   496	                .evaluate(&values)
   497	                .map_err(|error| format!("{} could not be evaluated: {error}", series.label))?;
   498	            y_min = y_min.min(y);
   499	            y_max = y_max.max(y);
   500	            sampled[index].push((progress, y));
   501	        }
   502	    }
   503	
   504	    if !y_min.is_finite() || !y_max.is_finite() {
   505	        return Err("the plot did not produce finite values".into());
   506	    }
   507	    if (y_max - y_min).abs() < f64::EPSILON {
   508	        let padding = y_max.abs().max(1.0) * 0.05;
   509	        y_min -= padding;
   510	        y_max += padding;
   511	    }
   512	    let span = y_max - y_min;
   513	    let paths = sampled
   514	        .into_iter()
   515	        .map(|points| {
   516	            points
   517	                .into_iter()
   518	                .enumerate()
   519	                .map(|(index, (x, y))| {
   520	                    let command = if index == 0 { 'M' } else { 'L' };
   521	                    format!(
   522	                        "{command}{:.3},{:.3}",
   523	                        x * 120.0,
   524	                        60.0 - (y - y_min) / span * 60.0
   525	                    )
   526	                })
   527	                .collect::<Vec<_>>()
   528	                .join(" ")
   529	        })
   530	        .collect();
   531	    Ok(SampledPlot {
   532	        paths,
   533	        y_min,
   534	        y_max,
   535	    })
   536	}
