   676	                                        class="interactive-plot__range"
   677	                                        type="range"
   678	                                        min=parameter.min.to_string()
   679	                                        max=parameter.max.to_string()
   680	                                        step=parameter.step.to_string()
   681	                                        prop:value=move || values.with(|current| current.get(&value_id).copied().unwrap_or(range_parameter.value).to_string())
   682	                                        aria-label=format!("{} slider", parameter.label)
   683	                                        on:input=move |event| { update_parameter(values, &range_parameter, &event_target_value(&event)); }
   684	                                        on:change=move |event| {
   685	                                            if let Some(value) = update_parameter(values, &commit_parameter, &event_target_value(&event)) {
   686	                                                let parameters = values.get_untracked();
   687	                                                daemon_range.send_component_event(component_id_range.clone(), json!({
   688	                                                    "type": "parameters_changed",
   689	                                                    "payload": { "parameters": parameters, "changed": { "id": commit_parameter.id, "value": value } }
   690	                                                }));
   691	                                            }
   692	                                        }
   693	                                    />
   694	                                    <label class="interactive-plot__number-wrap" for=number_label_id>
   695	                                        <span class="interactive-plot__sr-only">{format!("{} value", parameter.label)}</span>
   696	                                        <input
   697	                                            id=number_id
   698	                                            class="interactive-plot__number"
   699	                                            type="number"
   700	                                            min=parameter.min.to_string()
   701	                                            max=parameter.max.to_string()
   702	                                            step=parameter.step.to_string()
   703	                                            prop:value=move || values.with(|current| current.get(&number_value_id).copied().unwrap_or(number_parameter.value).to_string())
   704	                                            on:input=move |event| { update_parameter(values, &number_parameter, &event_target_value(&event)); }
   705	                                            on:change=move |event| {
   706	                                                if let Some(value) = update_parameter(values, &number_commit_parameter, &event_target_value(&event)) {
   707	                                                    let parameters = values.get_untracked();
   708	                                                    daemon_number.send_component_event(component_id_number.clone(), json!({
   709	                                                        "type": "parameters_changed",
   710	                                                        "payload": { "parameters": parameters, "changed": { "id": number_commit_parameter.id, "value": value } }
   711	                                                    }));
   712	                                                }
   713	                                            }
   714	                                        />
   715	                                        {(!unit.is_empty()).then(|| view! { <span class="interactive-plot__unit">{unit}</span> })}
   716	                                    </label>
   717	                                </div>
   718	                            </fieldset>
   719	                        }
   720	                    }).collect::<Vec<_>>()}
   721	                </div>
   722	            })}
   723	        </section>
   724	    }
   725	    .into_any()
   726	}
