   728	#[cfg(test)]
   729	mod tests {
   730	    use super::*;
   731	
   732	    fn eval(source: &str, variables: &[(&str, f64)]) -> Result<f64, String> {
   733	        Parser::parse(source)?.evaluate(
   734	            &variables
   735	                .iter()
   736	                .map(|(name, value)| ((*name).into(), *value))
   737	                .collect(),
   738	        )
   739	    }
   740	
   741	    #[test]
   742	    fn expression_engine_supports_precedence_constants_functions_and_variables() {
   743	        assert_eq!(eval("2 + 3 * 4", &[]).unwrap(), 14.0);
   744	        assert_eq!(eval("2^3^2", &[]).unwrap(), 512.0);
   745	        assert!((eval("sin(pi / 2) + max(m, 2)", &[("m", 3.0)]).unwrap() - 4.0).abs() < 1e-10);
   746	        assert!(
   747	            (eval("exp(ln(e)) + sqrt(9) + abs(-2)", &[]).unwrap() - (std::f64::consts::E + 5.0))
   748	                .abs()
   749	                < 1e-10
   750	        );
   751	    }
   752	
   753	    #[test]
   754	    fn expression_engine_rejects_unknown_or_non_finite_work() {
   755	        assert!(eval("unknown(1)", &[]).is_err());
   756	        assert!(eval("missing + 1", &[]).is_err());
   757	        assert!(eval("1 / 0", &[]).is_err());
   758	        assert!(Parser::parse(&"1".repeat(MAX_EXPRESSION_LEN + 1)).is_err());
   759	    }
   760	
   761	    fn valid_props() -> Value {
   762	        json!({
   763	            "title": "Decay",
   764	            "parameters": [{"id":"rate", "min":0.1, "max":3.0, "value":1.0}],
   765	            "plot": {
   766	                "x": {"min":0.0, "max":10.0, "samples":32},
   767	                "series": [{"label":"Value", "expression":"exp(-rate*x)"}]
   768	            },
   769	            "metrics": [{"label":"Half life", "expression":"ln(2)/rate"}]
   770	        })
   771	    }
   772	
   773	    #[test]
   774	    fn config_clamps_values_and_sample_work() {
   775	        let mut props = valid_props();
   776	        props["parameters"][0]["value"] = json!(99.0);
   777	        props["plot"]["x"]["samples"] = json!(50_000);
   778	        let config = PlotConfig::parse(&props).unwrap();
   779	        assert_eq!(config.parameters[0].value, 3.0);
   780	        assert_eq!(config.x.samples, MAX_SAMPLES);
   781	    }
   782	
   783	    #[test]
   784	    fn config_rejects_malformed_and_excessive_props() {
   785	        assert!(PlotConfig::parse(&json!({})).is_err());
   786	        let mut props = valid_props();
   787	        props["parameters"] = Value::Array(
   788	            (0..=MAX_PARAMETERS)
   789	                .map(|index| {
   790	                    json!({
   791	                        "id": format!("p{index}"), "min": 0, "max": 1
   792	                    })
   793	                })
   794	                .collect(),
   795	        );
   796	        assert!(PlotConfig::parse(&props).is_err());
   797	    }
   798	
   799	    #[test]
   800	    fn sampled_plot_is_finite_and_stays_inside_viewbox() {
   801	        let config = PlotConfig::parse(&valid_props()).unwrap();
   802	        let parameters = BTreeMap::from([("rate".into(), 1.0)]);
   803	        let plot = sample_plot(&config, &parameters).unwrap();
   804	        assert_eq!(plot.paths.len(), 1);
   805	        assert!(plot.y_min.is_finite() && plot.y_max.is_finite());
   806	        for pair in plot.paths[0].split_whitespace() {
   807	            let (_, coordinates) = pair.split_at(1);
   808	            let (x, y) = coordinates.split_once(',').unwrap();
   809	            assert!((0.0..=120.0).contains(&x.parse::<f64>().unwrap()));
   810	            assert!((0.0..=60.0).contains(&y.parse::<f64>().unwrap()));
   811	        }
   812	    }
   813	}

