   328	impl PlotConfig {
   329	    fn parse(props: &Value) -> Result<Self, String> {
   330	        let parameters_json = props
   331	            .get("parameters")
   332	            .and_then(Value::as_array)
   333	            .ok_or("parameters must be an array")?;
   334	        if parameters_json.len() > MAX_PARAMETERS {
   335	            return Err(format!("at most {MAX_PARAMETERS} parameters are supported"));
   336	        }
   337	
   338	        let plot = props.get("plot").ok_or("plot is required")?;
   339	        let x_json = plot.get("x").ok_or("plot.x is required")?;
   340	        let x_id = text(x_json, "id")
   341	            .unwrap_or_else(|| "x".into())
   342	            .to_ascii_lowercase();
   343	        if !valid_identifier(&x_id) || matches!(x_id.as_str(), "pi" | "e") {
   344	            return Err("plot.x.id must be a valid non-reserved variable name".into());
   345	        }
   346	        let x_min = finite_number(x_json, "min")?;
   347	        let x_max = finite_number(x_json, "max")?;
   348	        if x_min >= x_max {
   349	            return Err("plot.x.min must be less than plot.x.max".into());
   350	        }
   351	        let samples = x_json
   352	            .get("samples")
   353	            .and_then(Value::as_u64)
   354	            .unwrap_or(128)
   355	            .clamp(2, MAX_SAMPLES as u64) as usize;
   356	        let x = Axis {
   357	            id: x_id.clone(),
   358	            label: text(x_json, "label").unwrap_or_else(|| x_id.clone()),
   359	            min: x_min,
   360	            max: x_max,
   361	            samples,
   362	        };
   363	
   364	        let mut ids = BTreeSet::from([x_id, "pi".into(), "e".into()]);
   365	        let mut parameters = Vec::with_capacity(parameters_json.len());
   366	        for raw in parameters_json {
   367	            let id = text(raw, "id")
   368	                .ok_or("every parameter requires an id")?
   369	                .to_ascii_lowercase();
   370	            if !valid_identifier(&id) || !ids.insert(id.clone()) {
   371	                return Err(format!(
   372	                    "parameter id '{id}' is invalid, reserved, or duplicated"
   373	                ));
   374	            }
   375	            let min = finite_number(raw, "min")?;
   376	            let max = finite_number(raw, "max")?;
   377	            if min >= max {
   378	                return Err(format!("parameter '{id}' min must be less than max"));
   379	            }
   380	            let range = max - min;
   381	            let step = raw
   382	                .get("step")
   383	                .and_then(Value::as_f64)
   384	                .filter(|step| step.is_finite() && *step > 0.0)
   385	                .unwrap_or(range / 100.0)
   386	                .min(range);
   387	            let value = raw
   388	                .get("value")
   389	                .and_then(Value::as_f64)
   390	                .filter(|value| value.is_finite())
   391	                .unwrap_or(min)
   392	                .clamp(min, max);
   393	            parameters.push(Parameter {
   394	                label: text(raw, "label").unwrap_or_else(|| id.clone()),
   395	                unit: text(raw, "unit").unwrap_or_default(),
   396	                id,
   397	                min,
   398	                max,
   399	                step,
   400	                value,
   401	            });
   402	        }
   403	
   404	        let series_json = plot
   405	            .get("series")
   406	            .and_then(Value::as_array)
   407	            .ok_or("plot.series must be an array")?;
   408	        if series_json.is_empty() || series_json.len() > MAX_SERIES {
   409	            return Err(format!(
   410	                "plot.series must contain 1 to {MAX_SERIES} entries"
   411	            ));
   412	        }
   413	        let mut series = Vec::with_capacity(series_json.len());
   414	        for (index, raw) in series_json.iter().enumerate() {
   415	            let source = text(raw, "expression")
   416	                .ok_or_else(|| format!("series {} requires an expression", index + 1))?;
   417	            series.push(Series {
   418	                label: text(raw, "label").unwrap_or_else(|| format!("Series {}", index + 1)),
   419	                expression: Parser::parse(&source)
   420	                    .map_err(|error| format!("series {}: {error}", index + 1))?,
   421	            });
   422	        }
   423	
   424	        let metrics_json = props
   425	            .get("metrics")
   426	            .and_then(Value::as_array)
   427	            .cloned()
   428	            .unwrap_or_default();
   429	        if metrics_json.len() > MAX_METRICS {
   430	            return Err(format!("at most {MAX_METRICS} metrics are supported"));
   431	        }
   432	        let mut metrics = Vec::with_capacity(metrics_json.len());
   433	        for (index, raw) in metrics_json.iter().enumerate() {
   434	            let source = text(raw, "expression")
   435	                .ok_or_else(|| format!("metric {} requires an expression", index + 1))?;
   436	            metrics.push(Metric {
   437	                label: text(raw, "label").unwrap_or_else(|| format!("Metric {}", index + 1)),
   438	                expression: Parser::parse(&source)
   439	                    .map_err(|error| format!("metric {}: {error}", index + 1))?,
   440	                unit: text(raw, "unit").unwrap_or_default(),
   441	                precision: raw
   442	                    .get("precision")
   443	                    .and_then(Value::as_u64)
   444	                    .unwrap_or(2)
   445	                    .min(6) as usize,
   446	            });
   447	        }
   448	
   449	        Ok(Self {
   450	            title: text(props, "title").unwrap_or_default(),
   451	            description: text(props, "description").unwrap_or_default(),
   452	            parameters,
   453	            x,
   454	            y_label: text(plot, "y_label").unwrap_or_default(),
   455	            series,
   456	            metrics,
   457	        })
   458	    }
   459	}
