   567	    let config = PlotConfig::parse(&kind_props);
   568	    let Ok(config) = config else {
   569	        return view! {
   570	            <div class="component-interactive-plot component-interactive-plot--error" role="status">
   571	                <strong>"Interactive plot unavailable"</strong>
   572	                <span>{config.expect_err("checked above")}</span>
   573	            </div>
   574	        }
   575	        .into_any();
   576	    };
   577	    let initial = config
   578	        .parameters
   579	        .iter()
   580	        .map(|parameter| (parameter.id.clone(), parameter.value))
   581	        .collect::<BTreeMap<_, _>>();
   582	    let values = RwSignal::new(initial);
   583	
   584	    let graph_config = config.clone();
   585	    let metric_config = config.clone();
   586	    let title = config.title.clone();
   587	    let aria_label = if title.is_empty() {
   588	        "Interactive plot".to_string()
   589	    } else {
   590	        title.clone()
   591	    };
   592	    let heading = title.clone();
   593	    let description = config.description.clone();
