   599	            {(!description.is_empty()).then(|| view! { <p class="interactive-plot__description">{description}</p> })}
   600	            <div class="interactive-plot__graph">
   601	                {move || match sample_plot(&graph_config, &values.get()) {
   602	                    Ok(plot) => {
   603	                        let y_max = format_value(plot.y_max, 2);
   604	                        let y_min = format_value(plot.y_min, 2);
   605	                        let x_min = format_value(graph_config.x.min, 2);
   606	                        let x_max = format_value(graph_config.x.max, 2);
   607	                        let paths = plot.paths.into_iter().enumerate().map(|(index, path)| view! {
   608	                            <path class=format!("interactive-plot__line interactive-plot__line--{}", index + 1) d=path></path>
   609	                        }).collect::<Vec<_>>();
   610	                        view! {
   611	                            <div class="interactive-plot__y-label">{graph_config.y_label.clone()}</div>
   612	                            <div class="interactive-plot__plot-area">
   613	                                <span class="interactive-plot__y-max">{y_max}</span>
   614	                                <svg viewBox="0 0 120 60" preserveAspectRatio="none" role="img" aria-label="Computed plot">
