   624	                            </div>
   625	                        }.into_any()
   626	                    }
   627	                    Err(error) => view! {
   628	                        <div class="interactive-plot__error" role="status">{error}</div>
   629	                    }.into_any(),
   630	                }}
   631	            </div>
   632	
   633	            {(!metric_config.metrics.is_empty()).then(|| view! {
